	protected Competency read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Competency" );

		Competency entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Competency with primary key" );
		msg.append( competencyId );
		
		CompetencyFetchOneSummary fetchOneSummary = new CompetencyFetchOneSummary( competencyId );

		try {
			entity = CompetencyService.getCompetencyInstance().getCompetency( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Competency " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Competency.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Competency." );

		StringBuilder msg = new StringBuilder( "Failed to update a Competency : " );        
		Competency entity = read();
		UpdateCompetencyCommand command = generateUpdateCommand();
		command.setCompetencyId(entity.getCompetencyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Competency." );

			// for use later on...
			competencyId = entity.getCompetencyId();

			CompetencyService proxy = CompetencyService.getCompetencyInstance();  

			proxy.updateCompetency( command ).get();

			LOGGER.info( "-- Successfully saved Competency - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + competencyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Competency.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Competency." );

		Competency entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Competency with id " + competencyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Competency with id " + competencyId );

			throw e;
		}

		try{
			CompetencyService.getCompetencyInstance().delete( new DeleteCompetencyCommand( entity.getCompetencyId() ) ).get();
			LOGGER.info( "-- Successfully deleted Competency with id " + competencyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Competency with id " + competencyId );

			throw e;
		}
	}

	/**
	 * get all Competencys.
	 */
	protected List<Competency> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Competencys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Competency : " );        
		List<Competency> collection  = new ArrayList<>();

		try {
			// call the static get method on the CompetencyService
			collection = CompetencyService.getCompetencyInstance().getAllCompetency();
			assertNotNull( collection, "An Empty collection of Competency was incorrectly returned.");
			
			// Now print out the values
			Competency entity = null;            
			Iterator<Competency> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCompetencyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

